 m jsonb := $manifest${"batch":"sail-result-2025-2026-10-28","event":{"id":"77d3c6a5-83a8-5b98-b881-418267461f6b","slug":"sea-games-2025","name":"33rd SEA Games 2025 — Sailing","startDate":"2025-12-09","endDate":"2025-12-18","venue":"Samudara Kila Yachting Center, Chonburi, Thailand","organizer":"Yacht Racing Association of Thailand","classes":["ILCA 4","ILCA 6","ILCA 7","Optimist"]},"sheet":{"id":"ad71e545-0b78-5aac-aeeb-555a916747d0","slug":"sea-games-2025-optimist-girls","name":"33rd SEA Games 2025 — Sailing — Optimist Girls","boatClass":"Optimist","division":"Girls","raceCount":10,"totalFleetSize":6,"entryType":"individual","minParticipants":1,"maxParticipants":1},"officialSource":{"url":"https://www.racingrulesofsailing.org/documents/170952","title":"33rd SEA Games 2025 — Sailing — Optimist Girls results","type":"pdf","provisional":false,"publicationStatus":"final","visuallyReviewed":true,"pdfSearch":null},"results":[{"eventKey":"sea-games-2025","sourceDocument":170952,"sourcePage":2,"sourceClass":"Girl's Optimist","boatClass":"Optimist","division":"Girls","rank":1,"name":"PAILIN JAROENPON","sailOrBoardNumber":"THA 1253","club":"","nationality":"THA","gender":null,"officialBirthYear":null,"sourceBirthYear":"","grossScore":18.0,"nettScore":14.0,"races":[{"raceNumber":1,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":2,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":3,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":4,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":5,"score":4.0,"code":null,"discarded":true,"raw":"(4.0)"},{"raceNumber":6,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":7,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":8,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":9,"score":3.0,"code":null,"discarded":false,"raw":"3.0"},{"raceNumber":10,"score":1.0,"code":null,"discarded":false,"raw":"1.0"}],"handicap